import json, os, hashlib, pathlib
mp=pathlib.Path(os.environ['STAMPED_DELIVERY_MANIFEST']); m=json.loads(mp.read_bytes()); root=mp.parent
expected={e['path'] for e in m['entries']}; actual=set()
for base,dirs,files in os.walk(root,followlinks=False):
 relbase=pathlib.Path(base).relative_to(root)
 for x in dirs+files:
  p=relbase/x; actual.add(str(p))
missing=sorted(expected-actual); extra=sorted(actual-expected)
bad=[]
for e in m['entries']:
 p=root/e['path']
 if e['kind']=='file' and p.exists():
  d=os.readlink(p).encode() if p.is_symlink() else p.read_bytes()
  if hashlib.sha256(d).hexdigest()!=e.get('sha256') or len(d)!=e.get('size',len(d)):bad.append((e['path'],'hash,size'))
